-- +goose Up
-- The client's aluminium list (2026-11-17, an Excel file): intermediate products in seven groups (شمش، بیلت، ورق، پروفیل،
-- نبشی، لوله، قوطی), each sold in «بازار» in Toman/kg, plus the grades traded on the Iran Mercantile Exchange (one
-- product per traded symbol: grade and producer), free like every IME row. Rows the file repeated are added once. Additive
-- only: existing products, groups and prices are not touched (ON CONFLICT DO NOTHING), and a row appears on the site
-- once it has a price. Big groups show folded with their average price on the site (PriceTable, FOLD_AT).
-- Nothing happens on a fresh database (no metals yet when migrations run; the seed comes after).
INSERT INTO market.product_groups (metal_id, category_id, name_fa, name_en, sort)
SELECT m.id, c.id, g.name_fa, g.name_en, g.sort
FROM market.metals m JOIN market.product_categories c ON c.slug = 'intermediate',
     (VALUES
       ('شمش آلومینیوم', 'Aluminum ingot', 11),
       ('بیلت آلومینیوم', 'Aluminum billet', 12),
       ('ورق آلومینیوم', 'Aluminum sheet', 13),
       ('پروفیل آلومینیوم', 'Aluminum profile', 14),
       ('نبشی آلومینیومی', 'Aluminum angle', 15),
       ('لوله آلومینیوم', 'Aluminum pipe', 16),
       ('قوطی آلومینیومی', 'Aluminum box section', 17),
       ('شمش و آلیاژ بورس کالا', 'IME ingot and alloys', 18),
       ('بیلت و مفتول بورس کالا', 'IME billet and wire rod', 19)) AS g (name_fa, name_en, sort)
WHERE m.slug = 'aluminum'
ON CONFLICT (metal_id, category_id, name_fa) DO NOTHING;

